import XCTest
@testable import OnCare
final class HealthRecordTests: XCTestCase {
    let now = Date(timeIntervalSince1970: 1_760_000_000)
    func record() -> HealthRecord { HealthRecord(id: "hc:test", recordType: "BloodPressureRecord", date: now.addingTimeInterval(-60), title: "혈압", category: "생체", fields: ["systolic": .object(["inMillimetersOfMercury": .number(120)]), "diastolic": .object(["inMillimetersOfMercury": .number(80)]), "metadata": .object(["device": .object(["model": .text("Synthetic watch")])]), "samples": .array([.object(["time": .number((now.timeIntervalSince1970 - 60) * 1000), "beatsPerMinute": .number(72)])])]) }
    func testFullBackupPreservesUnitsSamplesAndSource() throws { let raw = record(); let backup = CareBackup(entries: [], healthRecords: [raw]); let restored = try CareBackup.decode(backup.encoded()); XCTAssertEqual(restored.healthRecords, [raw]); XCTAssertEqual(restored.healthRecords?.first?.fields, raw.fields) }
    func testPressureSummaryKeepsBothReadingsAndUnits() { XCTAssertEqual(record().summaryValue, "120 / 80 mmHg"); XCTAssertEqual(HealthValue.number(0.08).display, "0.08"); var medical = record(); medical.category = "의료"; XCTAssertEqual(medical.summaryValue, "원본 의료 문서") }
    func testCatalogAndInvalidRecords() throws { XCTAssertEqual(HealthRecord.types.count, 54); var raw = record(); raw.recordType = "UnknownRecord"; XCTAssertThrowsError(try raw.validate(now: now)); raw = record(); raw.date = now.addingTimeInterval(1); XCTAssertThrowsError(try raw.validate(now: now)); raw = record(); raw.fields["bad"] = .number(.infinity); XCTAssertThrowsError(try raw.validate(now: now)); XCTAssertThrowsError(try CareBackup(entries: [], healthRecords: [record(), record()]).validate(now: now)) }
    func testRecursivePayloadLimitAndAvailability() throws { var v = HealthValue.text("value"); for _ in 0..<14 { v = .array([v]) }; var nodes = 0; XCTAssertThrowsError(try v.validate(nodes: &nodes)); let bad = HealthAvailability(recordType: "HeartRateRecord", title: "심박", category: "생체", status: "permission", count: 3); XCTAssertThrowsError(try bad.validate()) }
    @MainActor func testSyncReplacesOnlySuccessfulTypesAndPreservesOtherPeer() throws { let folder = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString); try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true); defer { try? FileManager.default.removeItem(at: folder) }; let journal = Journal(directory: folder); let pair = SyncPair(version: 1, host: "192.168.1.2", port: 8766, peer: UUID().uuidString, token: String(repeating: "a", count: 43), fingerprint: String(repeating: "a", count: 64)); var raw = record(); raw.date = Date().addingTimeInterval(-60); let snapshot = HealthSnapshot(version: 1, peer: pair.peer, generatedAt: Date(), windowStart: Date().addingTimeInterval(-86400), kinds: ["health:BloodPressureRecord"], entries: [], healthRecords: [raw], availability: []); XCTAssertEqual(try journal.applyHealth(snapshot, pair: pair), 1); XCTAssertEqual(try journal.applyHealth(snapshot, pair: pair), 1); XCTAssertEqual(journal.state.healthRecords?.count, 1); var otherPair = pair; otherPair.peer = UUID().uuidString; var otherSnapshot = snapshot; otherSnapshot.peer = otherPair.peer; XCTAssertEqual(try journal.applyHealth(otherSnapshot, pair: otherPair), 1); XCTAssertEqual(journal.state.healthRecords?.count, 2); var failed = snapshot; failed.kinds = ["걸음"]; failed.healthRecords = []; XCTAssertEqual(try journal.applyHealth(failed, pair: pair), 0); XCTAssertEqual(journal.state.healthRecords?.count, 2); let reload = Journal(directory: folder); XCTAssertEqual(reload.state.healthRecords, journal.state.healthRecords); var empty = snapshot; empty.healthRecords = []; XCTAssertEqual(try journal.applyHealth(empty, pair: pair), 0); XCTAssertEqual(journal.state.healthRecords?.count, 1); XCTAssertEqual(journal.state.healthRecords?.first?.source, "health-connect:" + otherPair.peer) }
    func testWrongPermissionOrOriginCannotImport() throws { let pair = SyncPair(version: 1, host: "192.168.1.2", port: 8766, peer: UUID().uuidString, token: String(repeating: "a", count: 43), fingerprint: String(repeating: "a", count: 64)); var snapshot = HealthSnapshot(version: 1, peer: pair.peer, generatedAt: now, windowStart: now.addingTimeInterval(-86400), kinds: ["체중"], entries: [], healthRecords: [record()]); XCTAssertThrowsError(try snapshot.validate(pair: pair, now: now)); snapshot.kinds = ["health:BloodPressureRecord"]; try snapshot.validate(pair: pair, now: now); snapshot.healthRecords?[0].source = "health-connect:other"; XCTAssertThrowsError(try snapshot.validate(pair: pair, now: now)) }
}
